"""Validate -ApiUrl with the client's policy and write the temporary build module."""

import argparse
import json
from pathlib import Path
import runpy

ROOT = Path(__file__).resolve().parents[1]
normalize_api_url = runpy.run_path(str(ROOT / "app/core/api_config.py"))["normalize_api_url"]


def write_build_config(api_url: str, destination: Path) -> str:
    value = normalize_api_url(api_url, android=True)
    destination.write_text(
        "# Generated by scripts/build_android.ps1; contains only the public API URL.\n"
        f"ANDROID_API_BASE_URL = {json.dumps(value, ensure_ascii=True)}\n",
        encoding="utf-8",
    )
    return value


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--api-url", required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    try:
        print(write_build_config(args.api_url, args.output))
    except ValueError as exc:
        parser.exit(2, f"Android API configuration error: {exc}\n")
